declare(strict_types=1);use ImAuthenticator\Security;use ImAuthenticator\Web;$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$user=$auth->requireUser();$id=(int)($_GET['id']??0);$app=$db->one('SELECT * FROM applications WHERE id=? AND deleted_at IS NULL',[$id]);if(!$app||!$appAdmins->canManage((int)$user['id'],$id,'manage_config')){http_response_code(403);Web::page('Brak dostępu','<div class="alert danger">Brak uprawnień.</div>',$user);}$message='';if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);try{$action=(string)($_POST['action']??'save');if($action==='delete'){$cid=(int)$_POST['claim_id'];$db->execute('DELETE FROM claims_mappings WHERE id=? AND application_id=?',[$cid,$id]);$audit->write('application.claim.deleted','success',(int)$user['id'],null,$id,null,['claim_id'=>$cid]);}else{$name=trim((string)$_POST['claim_name']);$type=(string)$_POST['source_type'];$key=trim((string)($_POST['source_key']??''));$static=(string)($_POST['static_value']??'');$scope=trim((string)($_POST['required_scope']??''));if(!preg_match('/^[A-Za-z][A-Za-z0-9_.:-]{0,119}$/',$name))throw new RuntimeException('Nieprawidłowa nazwa claimu.');if(!in_array($type,['standard','attribute','role','static'],true))throw new RuntimeException('Nieprawidłowe źródło.');if(in_array($type,['standard','attribute'],true)&&$key==='')throw new RuntimeException('source_key jest wymagany.');if($scope!==''&&!$db->one('SELECT 1 FROM application_scopes WHERE application_id=? AND scope=?',[$id,$scope]))throw new RuntimeException('Scope nie należy do klienta.');$db->execute('INSERT INTO claims_mappings(application_id,claim_name,source_type,source_key,static_value,include_in_id_token,include_in_userinfo,required_scope) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE source_type=VALUES(source_type),source_key=VALUES(source_key),static_value=VALUES(static_value),include_in_id_token=VALUES(include_in_id_token),include_in_userinfo=VALUES(include_in_userinfo),required_scope=VALUES(required_scope)',[$id,$name,$type,$key!==''?$key:null,$type==='static'?$static:null,isset($_POST['id_token'])?1:0,isset($_POST['userinfo'])?1:0,$scope!==''?$scope:null]);$audit->write('application.claim.saved','success',(int)$user['id'],null,$id,null,['claim'=>$name,'source_type'=>$type]);}$message='<div class="alert success">Zapisano.</div>';}catch(Throwable$e){$message='<div class="alert danger">'.Web::e($e->getMessage()).'</div>';}}
$rows='';foreach($db->all('SELECT * FROM claims_mappings WHERE application_id=? ORDER BY claim_name',[$id])as$m)$rows.='<tr><td><code>'.Web::e($m['claim_name']).'</code></td><td>'.Web::e($m['source_type']).'</td><td>'.Web::e($m['source_key']?:$m['static_value']?:'—').'</td><td>'.((bool)$m['include_in_id_token']?'ID ':'').((bool)$m['include_in_userinfo']?'UserInfo':'').'</td><td>'.Web::e($m['required_scope']?:'—').'</td><td><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="claim_id" value="'.(int)$m['id'].'"><button class="danger" name="action" value="delete">Usuń</button></form></td></tr>';$scopes='<option value="">bez dodatkowego scope</option>';foreach($db->all('SELECT scope FROM application_scopes WHERE application_id=? ORDER BY scope',[$id])as$s)$scopes.='<option>'.Web::e($s['scope']).'</option>';$content='<div class="page-head"><div><h1>Claims — '.Web::e($app['name']).'</h1><p>Klient otrzymuje tylko jawnie skonfigurowane dane.</p></div><a class="button" href="/admin/applications/'.$id.'">Wróć</a></div>'.$message.'<section class="card"><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><label>Claim<input name="claim_name" placeholder="department" required></label><label>Źródło<select name="source_type"><option value="standard">Standardowe pole użytkownika</option><option value="attribute">Custom attribute</option><option value="role">Role aplikacyjne</option><option value="static">Wartość stała</option></select></label><label>source_key<input name="source_key" placeholder="department / email / name"></label><label>Wartość stała<input name="static_value"></label><label>Wymagany scope<select name="required_scope">'.$scopes.'</select></label><label class="checkbox"><input type="checkbox" name="id_token" checked> ID Token</label><label class="checkbox"><input type="checkbox" name="userinfo" checked> UserInfo</label><button class="primary" name="action" value="save">Zapisz mapping</button></form></section><div class="table-wrap"><table><thead><tr><th>Claim</th><th>Źródło</th><th>Klucz/wartość</th><th>Cel</th><th>Scope</th><th></th></tr></thead><tbody>'.($rows?:'<tr><td colspan="6">Brak mappingów.</td></tr>').'</tbody></table></div>';Web::page('Claims',$content,$user);
